(function(root){
'use strict';
function mount(host){
 const model=root.PLTimelineModel.create(root.PLTimelineSample),esc=MatchWorkspace.esc,node=id=>host.querySelector('#pl-tl-'+id);
 let cursor=0,selected=null,timer=null,active=false,epoch=0;
 const suggestions=['What happened here?','What supports this?','What is uncertain?','What happened earlier?'];
 host.innerHTML=`<section class="pl-timeline-main" aria-label="Full-match passage timeline"><div class="eyebrow">FULL-MATCH TIMELINE</div><div class="pl-timeline-title"><h2>A match, passage by passage.</h2><span>Retrospective candidate review</span></div><p class="pl-readout">Machine-transcribed commentary + sampled video · No live feed or full-match player tracking</p><div class="pl-timeline-transport"><label for="pl-tl-range">Source media cursor <strong id="pl-tl-clock"></strong></label><input id="pl-tl-range" type="range" min="0" max="${model.end}" step="any" value="0"><p id="pl-tl-time" class="pl-readout"></p><div class="pl-controls"><button id="pl-tl-play" aria-pressed="false">▶ Play passages</button><button id="pl-tl-previous">← Previous passage</button><button id="pl-tl-next">Next passage →</button><button id="pl-tl-start">↶ Start</button></div><p class="pl-stepping">One completed passage every 1.8 seconds. This steps through evidence endpoints; it is not video or match-speed playback.</p><p id="pl-tl-status" role="status" aria-live="polite"></p></div><p id="pl-tl-coverage" class="pl-readout"></p><article id="pl-tl-current" class="pl-timeline-current" aria-label="Selected completed passage"></article><section class="pl-observations" aria-labelledby="pl-tl-list-title"><h2 id="pl-tl-list-title">Available passages</h2><p id="pl-tl-empty" class="pl-readout"></p><ol id="pl-tl-list" class="pl-timeline-list"></ol></section><details class="pl-sources pl-timeline-sources"><summary>Source & limits ↗</summary><p>27 curated research passages from complete offline audio transcription and sampled video review of the official recording. Unverified machine transcription remains a candidate; sampled video is not continuous review or a complete incident feed. Replay and historical discussion stay distinct and never count as new events.</p><p>Each complete passage becomes available only after its media interval, every cited speech/context segment and scoped visual support have ended. Unknown support is withheld. This retrospective release rule does not establish live arrival or what was known then.</p><p>The cursor is source media time from 00:00:00 to ${esc(model.format(model.end))} (${model.end} seconds), using the reviewed audio/ledger endpoint. The separately acquired video extends to 5872.12 seconds. Edited halves and broadcast replays prevent a universal football-clock conversion. No current score, exact goal/contact time, player identity path, coordinates, movement statistics or full incident totals are inferred.</p><p>Earlier written reports and their conflicts are excluded from timeline answers. The separate three-second Estimated replay and 16 Reviewed captures retain their original limits.</p><p><a href="${esc(model.source.url)}" target="_blank" rel="noopener">Official full recording ↗</a> · Opens source material beyond the current cursor.</p><details><summary>Projection receipts</summary><pre tabindex="0">${esc(JSON.stringify(model.source,null,2))}</pre></details><p>Local deterministic prototype · No AI model, imported report facts or runtime media. Source-use, submission and publication limits remain separate.</p><div id="pl-tl-withheld"></div></details></section><section class="conversation pl-conversation pl-timeline-conversation" aria-label="Local questions about the selected timeline passage"><div class="conversation-bar"><div><span class="avatar" aria-hidden="true">↗</span><div><strong>The match timeline</strong><small>Local grounded answers · No AI</small></div></div></div><p class="pl-question-intro">Select a completed passage, then ask what supports it.</p><div id="pl-tl-thread" role="log" aria-live="polite" aria-label="Cursor and passage bound answers"></div><div id="pl-tl-suggestions">${suggestions.map(q=>`<button data-pl-timeline-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="pl-tl-composer"><label class="sr-only" for="pl-tl-draft">Question about the selected passage</label><input id="pl-tl-draft" autocomplete="off" placeholder="Ask about this passage…"><button type="submit" aria-label="Send timeline question">↑</button></form><p id="pl-tl-answer-status" role="status"></p><p class="pl-question-footer">Candidates, replay and uncertainty stay explicit</p></section>`;
 function clear(){node('thread').replaceChildren();node('draft').value='';node('answer-status').textContent='New answers use the current source cursor and selected passage.';}
 function pause(){epoch++;if(timer!==null)clearInterval(timer);timer=null;node('play').textContent='▶ Play passages';node('play').setAttribute('aria-pressed','false');node('status').textContent='Paused at source media '+model.format(cursor)+'.';}
 function paint(){
  const v=model.view(cursor,selected);selected=v.selected?.id||null;
  node('clock').textContent=model.format(cursor);node('time').textContent=cursor+' seconds of source media · Football clock and current score are not inferred.';
  node('range').value=String(cursor);node('range').setAttribute('aria-valuetext','Source media '+model.format(cursor)+', '+cursor+' seconds. '+(v.selected?'Selected completed passage '+v.selected.id+'.':'No completed evidence yet.'));
  node('coverage').textContent=v.gap?'No reviewed passage covers this media instant. Earlier completed evidence remains available.':'Only completed evidence is shown; a passage may need later supporting context.';
  const p=v.selected;
  node('current').innerHTML=p?`<span class="eyebrow">${esc(p.id)} · AVAILABLE AT ${esc(model.format(p.availableAt))} / ${p.availableAt} s</span><h2>${esc(p.title)}</h2><div class="pl-timeline-badges">${p.badges.map(b=>`<span>${esc(model.badgeLabels[b])}</span>`).join('')}</div><p>${esc(p.text)}</p><p class="pl-timeline-uncertainty"><strong>Uncertainty</strong> ${esc(p.uncertainty)}</p><small>Passage media ${esc(model.format(p.mediaInterval[0]))}–${esc(model.format(p.mediaInterval[1]))} · Complete supporting evidence has ended</small>`:'<h2>No completed evidence yet.</h2><p>Use Next passage to reach the first completed passage, or scrub the source media cursor.</p><p class="pl-timeline-uncertainty">This is a curated timeline. Empty coverage does not mean no football happened.</p>';
  node('empty').textContent=v.passages.length?'Choose an earlier available passage to ask about it at this cursor.':'No passage has completed at this cursor. Future passage content stays hidden.';
  node('list').innerHTML=v.passages.map(p=>`<li><button data-pl-timeline-id="${esc(p.id)}" aria-pressed="${p.id===selected}"><span>${esc(model.format(p.availableAt))} · ${esc(p.id)}</span><strong>${esc(p.title)}</strong><small>${p.badges.map(b=>esc(model.badgeLabels[b])).join(' · ')}</small></button></li>`).join('');
  node('withheld').innerHTML=v.withheld.length?'<h3>Withheld evidence</h3>'+v.withheld.map(p=>`<p>${esc(p.id)}: ${esc(p.reason)}</p>`).join(''):'';
  node('previous').disabled=model.adjacent(cursor,-1)===null;node('next').disabled=model.adjacent(cursor,1)===null;node('play').disabled=model.adjacent(cursor,1)===null;node('start').disabled=cursor===0;
 }
 function seek(value){const next=model.clamp(value);if(next===null)return;pause();cursor=next;selected=null;clear();paint();node('status').textContent='Paused at source media '+model.format(cursor)+'.';}
 function select(id){if(!model.eligible(cursor).some(p=>p.id===id))return;pause();selected=id;clear();paint();const button=Array.from(node('list').querySelectorAll('button[data-pl-timeline-id]')).find(button=>button.dataset.plTimelineId===id);button?.focus({preventScroll:true});node('status').textContent='Selected completed passage '+id+' at source media '+model.format(cursor)+'.';}
 function run(){if(!active||model.adjacent(cursor,1)===null)return;pause();clear();const token=epoch;timer=setInterval(()=>{if(!active||token!==epoch)return;const next=model.adjacent(cursor,1);if(next===null){pause();return;}cursor=next;selected=null;clear();paint();node('status').textContent='Completed passage at source media '+model.format(cursor)+'.';if(model.adjacent(cursor,1)===null){pause();node('status').textContent='End of the reviewed source. Passage playback stopped.';}},1800);node('play').textContent='Ⅱ Pause passages';node('play').setAttribute('aria-pressed','true');node('status').textContent='Stepping completed passages every 1.8 seconds.';}
 function ask(q){if(!active||!String(q??'').trim())return;pause();const answer=model.answer(cursor,selected,q),stamp='MATCH TIMELINE · SOURCE '+model.format(cursor)+' / '+cursor+' s · '+(answer.stamp.passageId||'NO COMPLETED PASSAGE');node('thread').insertAdjacentHTML('beforeend',MatchWorkspace.message(q,true,stamp,'')+MatchWorkspace.message(answer.text,false,stamp,'Local deterministic answer · No AI'));node('answer-status').textContent='Answer bound to '+cursor+' source seconds · '+(answer.stamp.passageId||'no completed passage')+'.';}
 node('range').addEventListener('input',e=>{if(active)seek(Number(e.target.value));});
 node('composer').addEventListener('submit',e=>{e.preventDefault();ask(node('draft').value);node('draft').value='';});
 host.addEventListener('click',e=>{if(!active)return;const b=e.target.closest('button');if(!b)return;if(b.dataset.plTimelineQuestion)ask(b.dataset.plTimelineQuestion);else if(b.dataset.plTimelineId)select(b.dataset.plTimelineId);else if(b.id==='pl-tl-play'){if(timer!==null){pause();clear();node('status').textContent='Paused at source media '+model.format(cursor)+'.';}else run();}else if(b.id==='pl-tl-start')seek(0);else if(b.id==='pl-tl-next'||b.id==='pl-tl-previous'){const next=model.adjacent(cursor,b.id==='pl-tl-next'?1:-1);if(next!==null)seek(next);}});
 paint();clear();
 return {activate(){active=true;pause();clear();paint();},deactivate(){active=false;pause();clear();},stop(){pause();clear();},isActive:()=>active};
}
root.PLTimeline={mount};
})(window);
